cd /app && rm -f config/initializers/bots.rb && rm -rf lib/bots && mkdir -p lib/middleware && cat > lib/middleware/bot_plain_text_bodies.rb <<'EOF'
# Bots post their message as the raw request body, which curl sends labelled as form data. Rack and Rails would
# parse that as form fields and fail on text such as "100%", so this relabels bot message bodies as plain text
# before anything reads them as a form. Multipart uploads keep their label, since their attachments need parsing.
class BotPlainTextBodies
  MESSAGES_PATH = %r{\A/rooms/[^/]+/[^/]+/messages\z}

  def initialize(app)
    @app = app
  end

  def call(env)
    if env["REQUEST_METHOD"] == "POST" && MESSAGES_PATH.match?(env["PATH_INFO"]) && !multipart?(env)
      env["CONTENT_TYPE"] = "text/plain"
    end

    @app.call(env)
  end

  private
    def multipart?(env)
      Rack::Request.new(env).media_type == "multipart/form-data"
    end
end
EOF
perl -0pi -e 's|    config.autoload_lib\(ignore: %w\[assets tasks rails_ext\]\)\n|    config.autoload_lib(ignore: %w[assets tasks rails_ext middleware])\n\n    # Bot messages are raw request bodies that must not be read as forms, so this has to run before Rack parses them.\n    require_relative "../lib/middleware/bot_plain_text_bodies"\n    config.middleware.insert_before Rack::MethodOverride, BotPlainTextBodies\n|' config/application.rb && git diff config/application.rb && bin/rails middleware 2>&1 | grep -n "BotPlain\|MethodOverride"; timeout 600 bin/rails test test/controllers/bots/scratch_probe_test.rb 2>&1 | tail -30

